	// Where a piece goes in the world, given its building's transform (location, turn, and Scale as the building is drawn)
	inline FTransform Place(const FTransform& Building, const FDecor& D)
	{
		const FVector BS = Building.GetScale3D();
		const FVector Spot = Building.TransformPosition(FVector(D.X, D.Y, D.Z));
		// (NX..NZ, when set: the surface the piece sits on, its up axis turned onto it, its front kept as near Yaw as the surface allows)
		const FQuat Local = (D.NX == 0.f && D.NY == 0.f && D.NZ == 0.f) ? FRotator(D.Pitch, D.Yaw, D.Roll).Quaternion()
			: FRotationMatrix::MakeFromZY(FVector(D.NX, D.NY, D.NZ), FRotator(0.f, D.Yaw, 0.f).RotateVector(FVector::YAxisVector)).ToQuat();
		const FQuat Turn = Building.GetRotation() * Local;
		const FVector Own(D.SX, D.SY, D.SZ);
		return FTransform(Turn, Spot, D.bScaleWithBuilding ? Own * BS : Own);
	}
	inline const FBuildingDecor* For(const TCHAR* Building)   // "TL_House" or "TL_Store"
	{
		for (const FBuildingDecor& B : Buildings) if (FCString::Stricmp(B.Building, Building) == 0) return &B;
		return nullptr;
	}
